input.sparql:
PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zoneName ?seriesId ?pointClass WHERE {
  ?point a brick:Air_Temperature ? .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?c WHERE {
  ?c a owl:equivalentClass ;
      rdfs:label ?l .
  FILTER(CONTAINS(LCASE(?l), "temperature"))
}

SELECT DISTINCT ?c WHERE {
  ?p rdf:type ?c .
  FILTER(CONTAINS(LCASE(STR(?c)), "temperature"))
}

SELECT ?s ?p ?o WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  ?s ?p ?o .
}
LIMIT 30

SELECT ?s ?p ?o WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#VAV_F2_Z01> ?p ?o .
}

SELECT DISTINCT ?t WHERE {
  ?x rdf:type ?t .
  FILTER(strstarts(str(?t), "https://brickschema.org/schema/Brick#"))
}

SELECT ?sensor ?ref ?z WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor brick:isPointOf ?pof }
  ?sensor ref:hasExternalReference ?ref .
  ?pof brick:feeds ?z .
}

SELECT ?z ?zlabel WHERE {
  ?z a brick:Room .
  ?z rdfs:label ?zlabel .
}

SELECT ?z ?zlabel ?z2 ?z2label WHERE {
  ?x a brick:Room ;
     owl:sameAs ?z .
  ?z rdfs:label ?zlabel .
  ?z brick:isPartOf ?z2 .
  ?z2 rdfs:label ?z2label .
}
LIMIT 5

SELECT ?z ?zlabel WHERE {
  ?z rdfs:label ?zlabel .
  FILTER(strstarts(?zlabel, "Zone"))
}

SELECT ?z ?t WHERE {
  ?z rdfs:label ?l .
  FILTER(strstarts(str(?l), "Perimeter_bot_ZN_2"))
}

SELECT ?x ?p ?o WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z01.Zone_Air_Temperature_Sensor> ?p ?o
}

SELECT ?x WHERE {
  ?x rdfs:label ?l .
  FILTER(strstarts(str(?l), "Zone_F2"))
}

SELECT ?z ?l WHERE {
  ?z a brick:Room .
  FILTER(strstarts(str(?z), "http://buildgraph.org/BG_large_office_2004_0000#Zone_"))
  OPTIONAL { ?z rdfs:label ?l }
}

SELECT ?z ?l WHERE {
  ?z a brick:Room .
  ?z rdfs:label ?l .
}

SELECT ?s WHERE {
  ?s a owl:equivalentClass ;
     rdfs:label "Zone_F2_Z01"
}

SELECT ?z ?t WHERE {
  ?z a ?t .
  FILTER(strstarts(str(?z), "http://buildgraph.org/BG_large_office_2004_0000#Zone_"))
}

SELECT ?z ?t ?l WHERE {
  ?z a brick:HVAC_Zone .
}

SELECT ?z ?p ?o WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z01> ?p ?o
}
